Вот пример кода на C++, который создает матрицу m x n такую, что каждый элемент матрицы равен произведению своего номера строки на номер столбца:

```cpp
#include <iostream>
#include <vector>

int main() {
    int m, n;
    std::cout << "Введите количество строк: ";
    std::cin >> m;
    std::cout << "Введите количество столбцов: ";
    std::cin >> n;

    std::vector<std::vector<int>> matrix(m, std::vector<int>(n));

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            matrix[i][j] = (i + 1) * (j + 1);
        }
    }

    std::cout << "Сгенерированная матрица:\n";
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            std::cout << matrix[i][j] << " ";
        }
        std::cout << "\n";
    }

    return 0;
}
```

Вы можете запустить этот код и ввести количество строк и столбцов для генерации соответствующей матрицы. Программа выведет сгенерированную матрицу, где каждый элемент равен произведению своего номера строки на номер столбца.

